description:
{
  "image_category": "MARKING_AND_SIGNAL",
  "summary": "Hình ảnh minh họa quy cách bố trí các loại vạch kẻ đường (vạch tim, vạch kênh hóa dòng xe, vạch dừng xe) tại một nút giao thông phức tạp, bao gồm cả đường cong và khu vực nhập/xuất làn.",
  "items": [
    {
      "identifier": "Vạch 1.1 (Vạch tim đường)",
      "visual_or_geometric_features": "Vạch đơn, đứt nét, màu vàng. Bề rộng nét vẽ b = 15 cm. Tỷ lệ đoạn nét liền L1/L2 = 1:2.",
      "meaning_or_specification": "Dùng để phân chia hai chiều xe chạy ngược chiều. Xe được phép cắt qua để sử dụng làn ngược chiều từ cả hai phía."
    },
    {
      "identifier": "Vạch 1.3 (Vạch tim đường)",
      "visual_or_geometric_features": "Vạch đôi song song, nét liền, màu vàng. Bề rộng nét vẽ b = 15 cm. Khoảng cách phía trong hai mép vạch đơn nhỏ nhất là 15 cm, lớn nhất là 50 cm.",
      "meaning_or_specification": "Dùng để phân chia hai chiều xe chạy ngược chiều, xe không được lấn làn, không được đè lên vạch. Thường dùng cho đường có từ 4 làn xe cơ giới trở lên hoặc ở các vị trí cần thiết khác."
    },
    {
      "identifier": "Vạch 4.1 (Vạch kênh hóa dòng xe)",
      "visual_or_geometric_features": "Vạch gạch chéo (gạch chéo), màu vàng. Mỗi vạch rộng 45 cm, khoảng cách hai mép vạch 100 cm, nghiêng một góc 135° theo chiều ngược chiều kim đồng hồ so với hướng chuyển động của xe.",
      "meaning_or_specification": "Dùng để giới hạn các phần mặt đường không sử dụng cho xe chạy mà sử dụng để kênh hóa các dòng giao thông. Xe không được lấn vạch hoặc cắt qua trừ trường hợp khẩn cấp."
    },
    {
      "identifier": "Vạch 7.1 (Vạch dừng xe)",
      "visual_or_geometric_features": "Vạch liền nét, màu trắng (hoặc vàng tùy ngữ cảnh cụ thể nhưng thường là vạch dừng xe chuẩn), nằm ở đầu làn chờ.",
      "meaning_or_specification": "Dùng để báo hiệu vị trí dừng xe bắt buộc. Xe không được vượt qua vạch này khi tín hiệu đèn không cho phép."
    },
    {
      "identifier": "Vạch 5.1 (Vạch dẫn hướng rẽ trái)",
      "visual_or_geometric_features": "Vạch đơn, đứt nét, màu trắng (hoặc màu tương ứng với vạch phân chia hai chiều), kéo dài qua phạm vi nút giao.",
      "meaning_or_specification": "Dùng để định hướng quỹ đạo cho dòng xe rẽ trái. Xe có thể cắt qua vạch khi cần thiết."
    },
    {
      "identifier": "Vạch 3.1 (Vạch giới hạn mép phần đường xe chạy)",
      "visual_or_geometric_features": "Vạch đơn, liền nét, màu trắng, bề rộng 15-20 cm.",
      "meaning_or_specification": "Dùng để xác định mép ngoài phần đường xe chạy hoặc phân cách làn xe cơ giới và làn xe thô sơ."
    }
  ]
}
